"""Independently check the fixed literals used by the MoonBit white-box tests."""
import ast
import pathlib
import re

source = (pathlib.Path(__file__).resolve().parents[1] / "format_wbtest.mbt").read_text(encoding="utf-8")
# Literal expected bytes are deliberately hand listed, not generated by MoonBit.
expected = {
    0: "0000000000000000", 1: "0100000000000000",
    -1: "0100000000000080", 255: "ff00000000000000",
    -255: "ff00000000000080", 256: "0001000000000000",
    -256: "0001000000000080", 9223372036854775807: "ffffffffffffff7f",
    -9223372036854775807: "ffffffffffffffff",
}
pattern = r'assert_eq\(\s*encode_int\(\s*(-?\d+)L\s*\),\s*Ok\(\s*(b"(?:\\.|[^"\\])*")\s*\)\s*,?\s*\)'
found = [(int(n), ast.literal_eval(b)) for n, b in re.findall(pattern, source)]
assert len(found) == len(expected) and {n for n, _ in found} == expected.keys()
for number, literal in found:
    assert literal.hex() == expected[number]
    magnitude = abs(number)
    independently_encoded = bytearray(magnitude.to_bytes(8, "little"))
    if number < 0:
        independently_encoded[7] |= 0x80
    assert literal == independently_encoded
    decoded = int.from_bytes(literal[:7] + bytes([literal[7] & 0x7f]), "little")
    assert (-decoded if literal[7] & 0x80 else decoded) == number
decode_pattern = r'decode_int\(\s*(b"(?:\\.|[^"\\])*")\s*,\s*0\s*,\s*Header\s*\)\s*,\s*Ok\(\s*(-?\d+)L'
decoded_literals = [(ast.literal_eval(b), int(n)) for b, n in re.findall(decode_pattern, source)]
assert len(decoded_literals) == 10
for literal, number in decoded_literals:
    magnitude = int.from_bytes(literal[:7] + bytes([literal[7] & 0x7f]), "little")
    assert (-magnitude if literal[7] & 0x80 else magnitude) == number
    assert literal.hex() == ("0000000000000080" if number == 0 and literal[7] & 0x80 else expected[number])

# Read the two explicit valid header literals actually exercised in MoonBit.
headers = re.findall(r'let patch\s*=\s*(b"(?:\\.|[^"\\])*")', source)
assert len(headers) == 2
for token, length, new, end in [(headers[0], 40, 0, 40), (headers[1], 37, 1, 37)]:
    patch = ast.literal_eval(token)
    assert len(patch) == length and patch[:8] == b"BSDIFF40"
    def read_int(raw):
        magnitude = int.from_bytes(raw[:7] + bytes([raw[7] & 0x7f]), "little")
        return -magnitude if raw[7] & 0x80 else magnitude
    control, diff, new_size = (read_int(patch[i:i + 8]) for i in (8, 16, 24))
    assert (control, diff, new_size) == (2, 3, new)
    assert (32, 32 + control, 32 + control + diff, len(patch)) == (32, 34, 37, end)
negative_zero = re.search(r'let zero\s*=\s*(b"BSDIFF40(?:\\x[0-9a-f]{2}){24}")', source)
assert negative_zero
raw = ast.literal_eval(negative_zero.group(1))
assert [raw[i:i+8].hex() for i in (8,16,24)] == ["0000000000000080"] * 3
# Check the invalid header literals and the expected category/location in MoonBit.
invalid_pattern = r'expect_failure\(\s*(b"(?:\\.|[^"\\])*"),\s*test_limits\(\),\s*(InvalidField|IntegerOverflow|TruncatedData),\s*Header,\s*(None|Some\("\w+"\)),\s*Some\((\d+)L\),\s*Some\("(\w+)"\)'
cases = re.findall(invalid_pattern, source)
assert len(cases) == 7
for token, expected_kind, block, offset, field in cases:
    patch = ast.literal_eval(token)
    assert len(patch) == 32 and patch[:8] == b"BSDIFF40"
    control, diff, output = (read_int(patch[i:i + 8]) for i in (8,16,24))
    if control < 0: actual = ("InvalidField", "None", 8, "control_length")
    elif diff < 0: actual = ("InvalidField", "None", 16, "diff_length")
    elif output < 0: actual = ("InvalidField", "None", 24, "new_size")
    elif 32 + control > 2**63 - 1: actual = ("IntegerOverflow", 'Some("control")', 8, "control_length")
    elif 32 + control + diff > 2**63 - 1: actual = ("IntegerOverflow", 'Some("diff")', 16, "diff_length")
    elif 32 + control > len(patch): actual = ("TruncatedData", 'Some("control")', 8, "control_length")
    elif 32 + control + diff > len(patch): actual = ("TruncatedData", 'Some("diff")', 16, "diff_length")
    else: raise AssertionError("invalid vector accepted")
    assert actual == (expected_kind, block, int(offset), field)
print("9 fixed integer vectors, negative zero, 2 valid and 7 invalid headers verified")
